pub(in crate::encrypt::aes) fn double(byte: u8) -> u8 {
    let reduction_mask = 0_u8.wrapping_sub(byte >> 7);
    (byte << 1) ^ (0x1b & reduction_mask)
}

pub(super) fn decrypt_pdf_cbc(&self, input: &[u8]) -> Result<Vec<u8>, AesCbcError> {
    let Some((iv, ciphertext)) = input.split_first_chunk::<BLOCK_LEN>() else {
        return Err(AesCbcError::InvalidLength);
    };
    let (blocks, remainder) = ciphertext.as_chunks::<BLOCK_LEN>();
    if blocks.is_empty() || !remainder.is_empty() {
        return Err(AesCbcError::InvalidLength);
    }

    Self::remove_pdf_padding(self.decrypt_cbc_blocks(iv, blocks))
}

pub(super) fn decrypt_ecb_block(&self, ciphertext: &Block) -> Block {
    BlockState::decrypt(*ciphertext, &self.round_keys)
}

pub(super) fn new_256(key: &[u8; KEY_256_LEN]) -> Self {
    let mut rounds = [[0; WORDS_PER_ROUND]; ROUND_KEYS_256];
    let [first, second, middle @ .., last] = &mut rounds;
    let (key_words, _) = key.as_chunks::<WORD_LEN>();
    for (word, bytes) in first.iter_mut().chain(second.iter_mut()).zip(key_words) {
        *word = u32::from_be_bytes(*bytes);
    }

    let mut older = *first;
    let mut previous = *second;
    let mut round_constant = 1;
    // AES-256 はラウンド定数を使う鍵と、SubWord だけを使う鍵を交互に作る。
    let (pairs, _) = middle.as_chunks_mut::<2>();
    for [even, odd] in pairs {
        *even = Self::expand_with_round_constant(older, &previous, &mut round_constant);
        let [.., last_word] = *even;
        *odd = Self::xor_chain(previous, Self::sub_word(last_word));

        older = *even;
        previous = *odd;
    }
    *last = Self::expand_with_round_constant(older, &previous, &mut round_constant);

    Self(ExpandedKeys::Aes256(rounds))
}

pub(super) fn split(&self) -> (&RoundKey, &[RoundKey], &RoundKey) {
    match &self.0 {
        ExpandedKeys::Aes128([first, middle @ .., last]) => (first, middle, last),
        ExpandedKeys::Aes256([first, middle @ .., last]) => (first, middle, last),
    }
}

pub(super) fn decrypt(ciphertext: Block, round_keys: &RoundKeys) -> Block {
    let (first, middle, last) = round_keys.split();
    let mut state = Self(ciphertext);
    state.add_round_key(last);

    for key in middle.iter().rev() {
        state.inv_shift_rows();
        state.inv_sub_bytes();
        state.add_round_key(key);
        state.inv_mix_columns();
    }

    state.inv_shift_rows();
    state.inv_sub_bytes();
    state.add_round_key(first);
    state.0
}
